// Function to calculate the sum of digits of a number
function SumOfDigits(n: int) : int
{
    var sum: int := 0;
    var absN := if n < 0 then -n else n;

    while absN > 0
        invariant absN >= 0
    {
        sum := sum + (absN % 10);
        absN := absN / 10;
    }
    return if n < 0 then -sum else sum;
}

